function FindProxyForURL(url, host) {
  host = String(host || '').toLowerCase();
  if (host === 'avito.ru' || dnsDomainIs(host, '.avito.ru') || host === 'api.ipify.org') {
    return 'PROXY pool.proxy.market:10000';
  }
  return 'DIRECT';
}

